#: severity lama -> (probability, impact). Skor: rendah 4, sedang 9, tinggi 16, kritis 25,
#: sehingga tingkat yang diturunkan dari skor sama dengan severity sebelumnya.
SEVERITY_TO_SCALE = {"low": (2, 2), "medium": (3, 3), "high": (4, 4), "critical": (5, 5)}


def severity_to_scale(apps, schema_editor):
    Risk = apps.get_model("projects", "Risk")
    for risk in Risk.objects.all():
        probability, impact = SEVERITY_TO_SCALE.get(risk.severity, (3, 3))
        risk.probability, risk.impact, risk.score = probability, impact, probability * impact
        risk.save(update_fields=["probability", "impact", "score"])


